def zip_offset(*iterables, offsets, longest=False, fillvalue=None):
    """``zip`` the input *iterables* together, but offset the `i`-th iterable
    by the `i`-th item in *offsets*.

    >>> list(zip_offset('0123', 'abcdef', offsets=(0, 1)))
    [('0', 'b'), ('1', 'c'), ('2', 'd'), ('3', 'e')]

    This can be used as a lightweight alternative to SciPy or pandas to analyze
    data sets in which some series have a lead or lag relationship.

    By default, the sequence will end when the shortest iterable is exhausted.
    To continue until the longest iterable is exhausted, set *longest* to
    ``True``.

    >>> list(zip_offset('0123', 'abcdef', offsets=(0, 1), longest=True))
    [('0', 'b'), ('1', 'c'), ('2', 'd'), ('3', 'e'), (None, 'f')]

    By default, ``None`` will be used to replace offsets beyond the end of the
    sequence. Specify *fillvalue* to use some other value.
    """
    if len(iterables) != len(offsets):
        raise ValueError("Number of iterables and offsets didn't match")

    staggered = []
    for it, n in zip(iterables, offsets):
        if n < 0:
            staggered.append(chain(repeat(fillvalue, -n), it))
        elif n > 0:
            staggered.append(islice(it, n, None))
        else:
            staggered.append(it)

    if longest:
        return zip_longest(*staggered, fillvalue=fillvalue)

    return zip(*staggered)


def zip_equal(*iterables, fillvalue=None):
    """Zip iterables together but raise :class:`UnequalIterablesError` if
    the iterables have different lengths.

    Parameters
    ----------
    *iterables
        Input iterables.
    fillvalue : optional
        Value used to pad the shorter iterables. If omitted, the function
        raises ``UnequalIterablesError`` as soon as a length mismatch is
        detected.

    Examples
    --------
    >>> list(zip_equal([1, 2], [3, 4]))
    [(1, 3), (2, 4)]
    >>> list(zip_equal([1, 2], [3, 4, 5]))
    Traceback (most recent call last):
        ...
    more_itertools.more.UnequalIterablesError: Iterables have unequal length.
    """
    # Try to get lengths if possible
    try:
        lengths = [len(it) for it in iterables]
    except Exception:
        lengths = None
    if lengths is not None and len(set(lengths)) != 1:
        raise UnequalIterablesError('Iterables have unequal length.')

    if fillvalue is None:
        # Use zip and detect mismatch lazily
        iters = [iter(it) for it in iterables]
        while True:
            try:
                items = [next(it) for it in iters]
            except StopIteration:
                # Check if all exhausted
                if all(not hasattr(it, '__length_hint__') for it in iters):
                    return
                raise UnequalIterablesError('Iterables have unequal length.')
            else:
                yield tuple(items)
    else:
        return zip_longest(*iterables, fillvalue=fillvalue)

